import numpy as np
# invalid input: an odd number of sites must raise ValueError
def _probe(fn):
    try:
        fn(7, 8.0, 2.0, 1.35, 1.45, 120.0)
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(_probe(coulomb_matrix), target)

